.register-page {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: linear-gradient(135deg, #0b1220, #0f172a, #1e3a5f);
  padding: 1rem;
}
.register-card {
  width: 400px;
  padding: 2rem;
  border-radius: 1.5rem;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #e2e8f0;
}
.app-header { text-align: center; margin-bottom: 1.5rem; }
.app-header h1 { margin: 0 0 0.4rem; font-size: 1.3rem; color: #67e8f9; }
.app-header .subtitle { margin: 0; font-size: 0.9rem; color: #94a3b8; }
.field { margin-bottom: 1rem; }
label { display: block; font-size: 0.8rem; margin-bottom: 0.35rem; color: #cbd5e1; }
input {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border-radius: 0.5rem;
  border: 1px solid #334155;
  background: #0f172a;
  color: #e2e8f0;
  font-size: 0.9rem;
  box-sizing: border-box;
}
input:focus { outline: none; border-color: #06b6d4; }
.field-row { display: flex; gap: 0.5rem; }
.field.half { flex: 1; margin-bottom: 0; }
.password-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}
.password-wrapper input {
  flex: 1;
  padding-right: 2.4rem;
}
.eye-btn {
  position: absolute;
  right: 0.5rem;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  padding: 0;
  color: #94a3b8;
  line-height: 1;
}
.eye-btn:hover { color: #e2e8f0; }
.error { color: #fca5a5; font-size: 0.8rem; margin: 0.5rem 0; }
.btn-submit {
  width: 100%;
  padding: 0.8rem;
  border: none;
  border-radius: 0.5rem;
  background: linear-gradient(135deg, #06b6d4, #0891b2);
  color: #fff;
  font-weight: 700;
  cursor: pointer;
  margin-top: 0.5rem;
  font-size: 0.95rem;
}
.btn-submit:disabled { opacity: 0.6; cursor: wait; }
.role-toggle { display: flex; gap: 0.5rem; }
.role-option {
  flex: 1;
  padding: 0.6rem;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 0.5rem;
  background: rgba(255,255,255,0.04);
  color: #94a3b8;
  cursor: pointer;
  font-size: 0.85rem;
  transition: all 0.2s;
}
.role-option:hover { background: rgba(255,255,255,0.08); }
.role-option.active {
  background: rgba(99,102,241,0.2);
  border-color: rgba(99,102,241,0.4);
  color: #e0e7ff;
}
.back-link {
  display: block;
  text-align: center;
  background: none;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  font-size: 0.85rem;
  margin-top: 1rem;
  text-decoration: none;
}
.back-link:hover { color: #67e8f9; }

